// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {Owned} from "../src/Owned.sol";

contract InvMutTest is Test {
    Owned c;
    function setUp() public { c = new Owned(); }

    function testFuzz_property(address actor) public {
        vm.assume(actor != address(0));

        address initialOwner = c.owner();

        vm.prank(actor);
        bool ok;
        try c.transferOwnership(actor) {
            ok = true;
        } catch {
            ok = false;
        }

        address post = c.owner();
        if (actor != initialOwner) {
            assertTrue(post == initialOwner);
        } else {
            assertTrue(post != address(0));
        }
    }
}
